package com.coraline.client.renderer;
import com.coraline.entity.CharacterEntity;
import net.minecraft.client.renderer.entity.*;
import net.minecraft.resources.ResourceLocation;
public final class CharacterRenderer extends MobRenderer<CharacterEntity,CharacterModel>{
    private static final ResourceLocation WHITE=ResourceLocation.fromNamespaceAndPath("coraline","characters/cast_atlas.png");
    private final CharacterModel originalModel,elderlyModel;
    private CharacterModel performanceCostume,rescueCostume;
    public CharacterRenderer(EntityRendererProvider.Context context,String id){super(context,new CharacterModel(id),id.equals("cat")?.25F:.45F);originalModel=model;elderlyModel=id.equals("other_miss_spink")?new CharacterModel("miss_spink"):id.equals("other_miss_forcible")?new CharacterModel("miss_forcible"):null;if(elderlyModel!=null)addLayer(new ShowDisguiseLayer(this,new CharacterModel(id.equals("other_miss_spink")?"theatre_spink_costume":"theatre_forcible_costume")));addLayer(new net.minecraft.client.renderer.entity.layers.RenderLayer<CharacterEntity,CharacterModel>(this){@Override public void render(com.mojang.blaze3d.vertex.PoseStack pose,net.minecraft.client.renderer.MultiBufferSource buffers,int light,CharacterEntity actor,float limb,float amount,float partial,float age,float yaw,float pitch){if(!actor.characterId().equals("other_wybie")||actor.gameGesture()==0||actor.getMainHandItem().isEmpty())return;pose.pushPose();getParentModel().transformBone("right_forearm",pose);pose.translate(0,.35,0);pose.scale(.45F,.45F,.45F);net.minecraft.client.Minecraft.getInstance().getItemRenderer().renderStatic(actor.getMainHandItem(),net.minecraft.world.item.ItemDisplayContext.FIXED,light,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,pose,buffers,actor.level(),actor.getId());pose.popPose();}});}
    @Override public void render(CharacterEntity actor,float yaw,float partial,com.mojang.blaze3d.vertex.PoseStack pose,net.minecraft.client.renderer.MultiBufferSource buffers,int light){var frame=com.coraline.client.ShowActorPoseClient.frame(actor);boolean rescue=elderlyModel!=null&&frame!=null&&(frame.pose()==83||frame.pose()==84),costume=!rescue&&elderlyModel!=null&&frame!=null&&frame.reveal()<=0;if(rescue){if(rescueCostume==null)rescueCostume=new CharacterModel("evil_other_spink_forcible",actor.characterId().equals("other_miss_spink")?1:2);model=rescueCostume;}else if(costume){if(performanceCostume==null)performanceCostume=new CharacterModel(actor.characterId().equals("other_miss_spink")?"theatre_spink_costume":"theatre_forcible_costume");model=performanceCostume;}else model=originalModel;pose.pushPose();TheatreAerialPresentation.align(actor,partial,pose);super.render(actor,yaw,partial,pose,buffers,light);FirstEscapePresentation.companionEffects(actor,pose,buffers,light,partial);pose.popPose();model=originalModel;}
    @Override public ResourceLocation getTextureLocation(CharacterEntity actor){return WHITE;}
}
